        m = len(cnf)
        n = max(abs(x) for clause in cnf for x in clause)
        M = [[0] * (n + 1) for _ in range(m)]
        for i, clause in enumerate(cnf):
            for x in clause:
                if x > 0:
                    M[i][x] = 1
                else:
                    M[i][-x] = -1
        return M

    def matrix_multiplication(A, B):
        m, k, n = len(A), len(B[0]), len(B)
        C = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                for l in range(k):
                    C[i][j] += A[i][l] * B[l][j]
        return C

    def transpose(M):
        return [list(x) for x in zip(*M)]

    def gaussian_elimination(A, b):
        m, n = len(A), len(A[0])
        augmented_matrix = [A[i] + [b[i]] for i in range(m)]

        for pivot_row in range(n - 1):
            if augmented_matrix[pivot_row][pivot_row] == 0:
                return None  # No unique solution

            for row in range(pivot_row + 1, m):
                factor = augmented_matrix[row][pivot_row] / augmented_matrix[pivot_row][pivot_row]
                for col in range(n):
                    augmented_matrix[row][col] -= factor * augmented_matrix[pivot_row][col]

        x = [0] * n
        for i in range(n - 1, -1, -1):
            x[i] = augmented_matrix[i][-1]
            for j in range(i + 1, n):
                x[i] -= augmented_matrix[i][j] * x[j]
            x[i] /= augmented_matrix[i][i]

        return x

    def rank(matrix):
        m, n = len(matrix), len(matrix[0])
        row echelon_form = matrix[:]
        for pivot_row in range(min(m, n)):
            if row_echelon_form[pivot_row][pivot_row] == 0:
